	private class Renderer : GTableCellRenderer {
		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {

			object value = data.getValue();
			JTable table = data.getTable();
			int row = data.getRowViewIndex();
			int column = data.getColumnViewIndex();
			bool isSelected = data.isSelected();
			bool hasFocus = data.hasFocus();

			JComponent renderer = null;
			if (column == 0) {
				TableCellRenderer booleanRenderer = table.getDefaultRenderer(typeof(Boolean));
				renderer = (JComponent) booleanRenderer.getTableCellRendererComponent(table, value,
					isSelected, hasFocus, row, column);
			}
			else {
				renderer = (JComponent) base.getTableCellRendererComponent(data);
			}

			if (isSelected) {
				return renderer;
			}

			return renderer;
		}
	}

